             from b in BilletsNonVides
             select (s, a, b))
            .Where(e => (e.s.Bloquee is not { } j || (e.a + e.b).Of(j) == 0) && !Deborde(e.s.Stock + e.a + e.b))
            .ToArbitrary(),
